      i=(i+1)%256; j=(j+S[i])%256
      S[i],S[j]=S[j],S[i]
      -- 使用标准 Lua 位运算（若 bit32 存在则用 bit32，否则用自定义）
      local b = data:byte(k)
      local xor_val
      if bit32 then xor_val = bit32.bxor(b, S[(S[i]+S[j])%256])
      else xor_val = b ~ S[(S[i]+S[j])%256] end
      o[k]=string.char(xor_val)
    end
    return table.concat(o)
  end
